def solve_problem(initial_string):
    """
    Solve the string transformation puzzle.

    :param initial_string: The initial string to transform.
    :return: A list of rule indices applied to transform the string to empty.
    """
    rules = {
        0: "CBB",
        1: "DEAD",
        2: "EA",
        3: "ABC",
        4: "CBC"
    }

    string = list(initial_string)
    solution = []

    def apply_rule(index):
        if index in rules:
            pattern = rules[index]
            if string[:len(pattern)] == list(pattern):
                solution.append(index)
                string[:len(pattern)] = [''] * len(pattern)
                return True
        return False

    while string != [''] * len(string):
        for i in range(len(rules)):
            if apply_rule(i):
                break

    return {"problem_id": "051", "solution": solution}

